INSERT INTO t_1nf_repeating
SELECT
  i,
  CONCAT('Cust_', LPAD(i,4,'0')),
  CONCAT('555-01', LPAD((((i*1)%50)+1),2,'0')),
  CONCAT('555-02', LPAD((((i*7)%50)+1),2,'0')),
  CONCAT('555-03', LPAD((((i*11)%50)+1),2,'0')),
  CONCAT('cust', i, '@example.com'),
  CONCAT('City_', LPAD(((((i*19)%83)%8)+1),2,'0')),
  DATE_ADD('2023-06-01', INTERVAL ((i*23)%79) DAY),
  CONCAT('ST_', ((((i*17)%89)%4)+1)),
  CONCAT('N', ((((i*37)%71)%200)+1))
FROM seq WHERE i BETWEEN 1 AND 150;

-- t_2nf_partial: PK (order_id, product_id); product_name/unit_price <- product_id; order_date <- order_id.
CREATE TABLE t_2nf_partial (
  order_id INT,
  product_id INT,
  product_name VARCHAR(20),
  unit_price DECIMAL(10,2),
  qty INT,
  order_date DATE,
  ship_mode VARCHAR(8),
  warehouse VARCHAR(8),
  priority VARCHAR(8),
  note_txt VARCHAR(60),
  PRIMARY KEY (order_id, product_id)
) ENGINE=InnoDB;
INSERT INTO t_2nf_partial
SELECT
  (((i*7)%60)+1),
  (((i*11)%50)+1),
  CONCAT('Product_', LPAD((((i*11)%50)+1),3,'0')),
  (((((((i*11)%50)+1)*13)%400)/100)+5),
  ((((i*13)%97)%5)+1),
  DATE_ADD('2024-02-01', INTERVAL (((((i*7)%60)+1)*3)%28) DAY),
  CONCAT('SM_', ((((i*19)%83)%4)+1)),
  CONCAT('WH_', ((((i*23)%79)%6)+1)),
  CASE WHEN ((((i*29)%73)%2))=0 THEN 'HIGH' ELSE 'LOW' END,
  CONCAT('N', ((((i*31)%67)%200)+1))
FROM seq WHERE i BETWEEN 1 AND 300;

