  CONCAT('AB_', (((i-1) DIV 20)+1), '_', ((((i-1)%20) DIV 4)+1)),
  ((((i*13)%97)%90)+1),
  ((((i*17)%89)%5)+1),
  CONCAT('ST_', ((((i*19)%83)%4)+1)),
  CONCAT('City_', LPAD(((((i*23)%79)%8)+1),2,'0')),
  CASE WHEN ((((i*29)%73)%2))=0 THEN 'Y' ELSE 'N' END,
  CONCAT('N', ((((i*31)%67)%200)+1))
FROM seq WHERE i BETWEEN 1 AND 200;

