-- d_nulls: heavy NULLs, independent columns.
CREATE TABLE d_nulls (
  id INT PRIMARY KEY,
  c1 VARCHAR(12),
  c2 VARCHAR(12),
  c3 VARCHAR(12),
  n1 INT,
  note_txt VARCHAR(60),
  flag CHAR(1),
  qty INT
) ENGINE=InnoDB;
INSERT INTO d_nulls
SELECT
  i,
  CASE WHEN (i%10)<3 THEN NULL ELSE CONCAT('A', (((i*7)%40)+1)) END,
  CASE WHEN (i%10)<4 THEN NULL ELSE CONCAT('B', (((i*11)%35)+1)) END,
  CASE WHEN (i%10)<2 THEN NULL ELSE CONCAT('C', (((i*13)%28)+1)) END,
  CASE WHEN (i%10)<3 THEN NULL ELSE (((i*17)%89)+1) END,
  CASE WHEN (i%10)<5 THEN NULL ELSE CONCAT('N', ((((i*19)%83)%200)+1)) END,
  CASE WHEN ((((i*23)%79)%2))=0 THEN 'Y' ELSE 'N' END,
  ((((i*29)%73)%5)+1)
FROM seq WHERE i BETWEEN 1 AND 150;

-- d_near_fd: dept_id->dept_name with 2 dirty rows (1%).
CREATE TABLE d_near_fd (
  id INT PRIMARY KEY,
  dept_id INT,
  dept_name VARCHAR(20),
  hire_date DATE,
  salary INT,
  city VARCHAR(12),
  status VARCHAR(8),
  note_txt VARCHAR(60)
) ENGINE=InnoDB;
INSERT INTO d_near_fd
SELECT
  i,
  (((i*7)%25)+1),
  CASE WHEN i IN (40,121) THEN 'Dept_XX_WRONG' ELSE CONCAT('Dept_', LPAD((((i*7)%25)+1),2,'0')) END,
  DATE_ADD('2021-01-01', INTERVAL ((i*23)%79) DAY),
  ((((((i*29)%73)%50)+1)+30)*1000),
  CONCAT('City_', LPAD(((((i*19)%83)%8)+1),2,'0')),
  CONCAT('ST_', ((((i*17)%89)%4)+1)),
  CONCAT('N', ((((i*31)%67)%200)+1))
FROM seq WHERE i BETWEEN 1 AND 200;

-- d_dirty_pairs: every group has 2 disagreeing rows.
CREATE TABLE d_dirty_pairs (
  id INT PRIMARY KEY,
  pair_id INT,
  side VARCHAR(8),
  note_txt VARCHAR(60),
  flag CHAR(1),
  amt INT
) ENGINE=InnoDB;
INSERT INTO d_dirty_pairs
SELECT
  i,
  (((i-1) DIV 2)+1),
  CASE WHEN i%2=1 THEN 'LEFT' ELSE 'RIGHT' END,
  CONCAT('N', ((((i*13)%97)%200)+1)),
  CASE WHEN ((((i*17)%89)%2))=0 THEN 'Y' ELSE 'N' END,
  ((((i*19)%83)%500)+1)
FROM seq WHERE i BETWEEN 1 AND 120;

-- d_equiv_cols: 10-row lookup; code <-> country 1-1.
CREATE TABLE d_equiv_cols (
  code VARCHAR(8) PRIMARY KEY,
  country VARCHAR(20),
  capital VARCHAR(20),
  currency VARCHAR(12),
  note_txt VARCHAR(60)
) ENGINE=InnoDB;
INSERT INTO d_equiv_cols
SELECT
  CONCAT('CC', LPAD(i,2,'0')),
  CONCAT('Country_CC', LPAD(i,2,'0')),
  CONCAT('Capital_CC', LPAD(i,2,'0')),
  CONCAT('Cur_CC', LPAD(i,2,'0')),
  CONCAT('N', i)
FROM seq WHERE i BETWEEN 1 AND 10;

-- d_wide_text: LOB/JSON excluded from FD search.
CREATE TABLE d_wide_text (
  id INT PRIMARY KEY,
  title VARCHAR(120),
  body MEDIUMTEXT,
  attachment BLOB,
  meta JSON,
  created_date DATE,
  author VARCHAR(20)
) ENGINE=InnoDB;
INSERT INTO d_wide_text
SELECT
  i,
  CONCAT('Doc_', LPAD(i,4,'0'), '_', 'xxxxxxxxxxxxxxxxxxxx'),
  REPEAT(CONCAT('lorem-', ((i*1)%7), ' '), 30),
  REPEAT(CONCAT('bin-', ((i*1)%5), ';'), 40),
  CONCAT('{"k": ', ((i*1)%5), '}'),
  DATE_ADD('2023-01-01', INTERVAL ((i*23)%79) DAY),
  CONCAT('Author_', ((((i*29)%73)%10)+1))
FROM seq WHERE i BETWEEN 1 AND 80;

-- d_name_trap: naming suggests user_id->user_name; data disagrees.
CREATE TABLE d_name_trap (
  id INT PRIMARY KEY,
  user_id INT,
  user_name VARCHAR(20),
  signup_date DATE,
  status VARCHAR(8),
  city VARCHAR(12),
  logins INT,
  note_txt VARCHAR(60)
) ENGINE=InnoDB;
INSERT INTO d_name_trap
SELECT
  i,
  (((i*7)%50)+1),
  CONCAT('User_', LPAD(((((i*13)%97)%97)+1),3,'0')),
  DATE_ADD('2023-01-01', INTERVAL ((i*23)%79) DAY),
  CONCAT('ST_', ((((i*17)%89)%4)+1)),
  CONCAT('City_', LPAD(((((i*19)%83)%8)+1),2,'0')),
  ((((i*29)%73)%500)+1),
  CONCAT('N', ((((i*31)%67)%200)+1))
FROM seq WHERE i BETWEEN 1 AND 150;

-- t_big_sample: 55000 rows (> MAX_ROWS_PER_TABLE); transitive FD.
CREATE TABLE t_big_sample (
  id INT PRIMARY KEY,
  customer_id INT,
  customer_name VARCHAR(20),
  order_date DATE,
  qty INT,
  unit_price DECIMAL(10,2),
  status VARCHAR(8),
  ship_city VARCHAR(12),
  flag CHAR(1),
  note_txt VARCHAR(60)
) ENGINE=InnoDB;
INSERT INTO t_big_sample
SELECT
  i,
  (((i*7)%100)+1),
  CONCAT('Customer_', LPAD((((i*7)%100)+1),3,'0')),
  DATE_ADD('2024-01-05', INTERVAL ((i*23)%79) DAY),
  ((((i*13)%97)%5)+1),
  ((((((i*29)%73)%40)+1)+10)+0.99),
  CONCAT('ST_', ((((i*17)%89)%4)+1)),
  CONCAT('City_', LPAD(((((i*19)%83)%8)+1),2,'0')),
  CASE WHEN ((((i*31)%67)%2))=0 THEN 'Y' ELSE 'N' END,
  CONCAT('N', ((((i*37)%71)%200)+1))
FROM seq WHERE i BETWEEN 1 AND 55000;

